package br.com.erp.pos;
import br.com.erp.auth.*;
import br.com.erp.shared.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

@br.com.erp.shared.WorkflowAmounts @RestController @Validated @RequestMapping("/api/v1/sales-orders") @PreAuthorize("hasAuthority('salesorder:read')")
public class SalesOrderController {
 private final com.fasterxml.jackson.databind.ObjectMapper json;private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final Audit audit;private final CartPricing pricing;private final SaleService sales;private final CashService cash;
 public SalesOrderController(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,Audit audit,CartPricing pricing,SaleService sales,CashService cash,com.fasterxml.jackson.databind.ObjectMapper json){this.json=json;this.db=db;this.access=access;this.flow=flow;this.audit=audit;this.pricing=pricing;this.sales=sales;this.cash=cash;}
 public record Draft(@NotNull UUID requestId,@NotNull UUID branchId,UUID customerId,@NotBlank @Pattern(regexp="QUOTE|ORDER") String kind,@NotNull LocalDate validUntil,@NotNull @Size(max=500) String note,@NotEmpty @Size(max=100) List<SaleContracts.@NotNull @Valid ItemInput> items,@NotNull @Min(0) Long version){}
 public record Action(@NotNull UUID requestId,@NotNull @Min(0) Long version){}
 public record Conversion(@NotNull UUID requestId,@NotNull @Min(0) Long version,@NotNull @Valid SaleContracts.Input sale){}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
 private LocalDate today(){return LocalDate.now(ZoneId.of("America/Sao_Paulo"));}
 @GetMapping("/{id}") @Transactional(readOnly=true) public Map<String,Object> get(@AuthenticationPrincipal Actor a,@PathVariable UUID id){var rows=db.queryForList("SELECT * FROM sales_order WHERE tenant_id=? AND id=?",a.tenantId(),id);if(rows.isEmpty())throw flow.missing("Pedido/orçamento não encontrado.");var r=rows.getFirst();access.requireBranch(a,(UUID)r.get("branch_id"));r.put("items",pricing.decode((String)r.remove("items_json")));return r;}
 @GetMapping @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> list(@AuthenticationPrincipal Actor a,@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){String where=" WHERE o.tenant_id=? AND "+BranchAccess.predicate("o.branch_id");var ids=db.query("SELECT o.id FROM sales_order o"+where+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,i)->r.getObject(1,UUID.class),a.tenantId(),a.tenantId(),a.userId(),size,(long)page*size);return Map.of("items",ids.stream().map(id->get(a,id)).toList(),"total",db.queryForObject("SELECT COUNT(*) FROM sales_order o"+where,Long.class,a.tenantId(),a.tenantId(),a.userId()),"page",page,"size",size);}
 @PostMapping @PreAuthorize("hasAuthority('salesorder:read') and hasAuthority('salesorder:write')") @Transactional public Map<String,Object> create(@AuthenticationPrincipal Actor a,@Valid @RequestBody Draft input){return save(a,null,input);}
 @PutMapping("/{id}") @PreAuthorize("hasAuthority('salesorder:read') and hasAuthority('salesorder:write')") @Transactional public Map<String,Object> edit(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@Valid @RequestBody Draft input){return save(a,id,input);}
 private Map<String,Object> save(Actor a,UUID id,Draft input){flow.lock(a);access.requireBranch(a,input.branchId());Map<String,Object> current=id==null?null:get(a,id);var fields=new ArrayList<Object>(Arrays.asList("SALES_ORDER",id,input.branchId(),input.customerId(),input.kind(),input.validUntil(),input.note().trim(),input.version()));for(var l:input.items())Collections.addAll(fields,l.productId(),l.quantity(),l.expectedUnitPrice(),CartPricing.discount(l));String hash=flow.hash(fields.toArray());UUID replay=flow.replay(a,input.requestId(),"SALES_ORDER_SAVE",hash);if(replay!=null)return get(a,replay);if(input.validUntil().isBefore(today())||input.validUntil().getYear()>9999)throw flow.bad("Validade deve ser hoje ou futura.");if(current!=null&&(!current.get("status").equals("DRAFT")||((Number)current.get("version")).longValue()!=input.version()||!current.get("branch_id").equals(input.branchId())))throw flow.conflict("Pedido alterado, aprovado ou de outra filial.");if(current==null&&input.version()!=0)throw flow.conflict("Novo pedido exige versão zero.");if(db.queryForObject("SELECT COUNT(*) FROM branch WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),input.branchId())!=1)throw flow.missing("Filial ativa não encontrada.");if(input.customerId()!=null&&db.queryForObject("SELECT COUNT(*) FROM customer WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),input.customerId())!=1)throw flow.missing("Cliente ativo não encontrado.");var quote=pricing.quote(a,input.branchId(),input.items());UUID result=id==null?UUID.randomUUID():id;if(id==null)db.update("INSERT INTO sales_order(id,tenant_id,branch_id,customer_id,kind,status,valid_until,note,items_json,cart_hash,total,created_by) VALUES(?,?,?,?,?,'DRAFT',?,?,?,?,?,?)",result,a.tenantId(),input.branchId(),input.customerId(),input.kind(),input.validUntil(),input.note().trim(),pricing.encode(quote.items()),quote.hash(),quote.total(),a.userId());else db.update("UPDATE sales_order SET customer_id=?,kind=?,valid_until=?,note=?,items_json=?,cart_hash=?,total=?,version=version+1 WHERE tenant_id=? AND id=?",input.customerId(),input.kind(),input.validUntil(),input.note().trim(),pricing.encode(quote.items()),quote.hash(),quote.total(),a.tenantId(),id);flow.record(a,input.requestId(),"SALES_ORDER_SAVE",hash,result);audit.record(a,"SALES_ORDER_SAVED",result);return get(a,result);}
 @PostMapping("/{id}/{action:approve|reopen|cancel}") @PreAuthorize("hasAuthority('salesorder:read') and hasAuthority('salesorder:write')") @Transactional public Map<String,Object> action(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String action,@Valid @RequestBody Action input){flow.lock(a);var r=get(a,id);String hash=flow.hash(id,action,input.version());if(flow.replay(a,input.requestId(),"SALES_ORDER_ACTION",hash)!=null)return get(a,id);if(((Number)r.get("version")).longValue()!=input.version())throw flow.conflict("Pedido alterado.");String status=(String)r.get("status");if(!List.of("DRAFT","APPROVED").contains(status))throw flow.conflict("Pedido encerrado.");if(action.equals("approve")){flow.require(a,"salesorder:approve");if(!status.equals("DRAFT"))throw flow.conflict("Pedido já aprovado.");if(((java.sql.Date)r.get("valid_until")).toLocalDate().isBefore(today()))throw flow.conflict("Pedido vencido.");var lines=((List<?>)r.get("items")).stream().map(CartPricing.Line.class::cast).toList();var quote=pricing.quote(a,(UUID)r.get("branch_id"),lines.stream().map(CartPricing.Line::input).toList());if(!quote.hash().equals(r.get("cart_hash")))throw flow.conflict("Cadastro mudou. Atualize o rascunho.");}else if(action.equals("reopen")&&!status.equals("APPROVED"))throw flow.conflict("Somente aprovado pode reabrir.");db.update("UPDATE sales_order SET status=?,approved_by=?,version=version+1 WHERE tenant_id=? AND id=?",action.equals("approve")?"APPROVED":action.equals("cancel")?"CANCELLED":"DRAFT",action.equals("approve")?a.userId():null,a.tenantId(),id);flow.record(a,input.requestId(),"SALES_ORDER_ACTION",hash,id);audit.record(a,"SALES_ORDER_"+action.toUpperCase(Locale.ROOT),id);return get(a,id);}
 @PostMapping("/{id}/convert") @PreAuthorize("hasAuthority('salesorder:read') and hasAuthority('salesorder:write') and hasAuthority('pos:read') and hasAuthority('pos:sell') and hasAuthority('treasury:read') and hasAuthority('treasury:move')") @Transactional public Map<String,Object> convert(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@Valid @RequestBody Conversion input){flow.lock(a);var r=get(a,id);var sale=input.sale();if(!sale.requestId().equals(input.requestId())||sale.suspensionId()!=null||sale.suspensionVersion()!=null)throw flow.bad("Use a identidade da conversão e não vincule suspensão.");var session=cash.get(a,sale.sessionId());if(!session.branchId().equals(r.get("branch_id")))throw flow.conflict("Caixa deve pertencer à filial do pedido.");String hash=flow.hash("SALES_ORDER_CONVERT",id,input.version(),encode(sale));UUID replay=flow.replay(a,input.requestId(),"SALES_ORDER_CONVERT",hash);if(replay!=null){sales.complete(a,sale);return get(a,id);}if(!r.get("status").equals("APPROVED")||((Number)r.get("version")).longValue()!=input.version())throw flow.conflict("Aprove a versão atual antes de converter.");if(((java.sql.Date)r.get("valid_until")).toLocalDate().isBefore(today()))throw flow.conflict("Pedido vencido.");if(sale.loyaltyCustomerId()!=null&&!sale.loyaltyCustomerId().equals(r.get("customer_id")))throw flow.conflict("Cliente de fidelidade difere do pedido.");if(sale.credit()!=null&&!sale.credit().customerId().equals(r.get("customer_id")))throw flow.conflict("Cliente do crediário difere do pedido.");var quote=pricing.quote(a,session.branchId(),sale.items());if(!quote.hash().equals(r.get("cart_hash")))throw flow.conflict("Itens ou preços mudaram. Reabra e aprove novamente.");if(db.queryForObject("SELECT COUNT(*) FROM pos_sale WHERE tenant_id=? AND request_id=?",Long.class,a.tenantId(),sale.requestId())>0)throw flow.conflict("Identidade já usada por outra venda.");var completed=sales.complete(a,sale);db.update("UPDATE sales_order SET status='CONVERTED',sale_id=?,version=version+1 WHERE tenant_id=? AND id=?",completed.id(),a.tenantId(),id);flow.record(a,input.requestId(),"SALES_ORDER_CONVERT",hash,id);audit.record(a,"SALES_ORDER_CONVERTED",id);return get(a,id);}
}
